/**
 * This file contains functionality that was copy/pasted from underscore.js for debouncing.
 * If we need throttling we can add that in here too. Didn't want to
 */
export declare function debounce(func: (...args: Array<any>) => any, wait?: number, immediate?: boolean): any;
/**
 * Running the debounce function on an event handler can often break because
 * the event.target gets clobbered after the event bubbles outside the shadow-root.
 *
 * This function can extract the data from the event.target and then pump it into
 * the debounce function so that when the callback gets called asynchronously it
 * can access the data directly rather than getting a null pointer exception on event.target.
 * @param mutateFn A function that can grab data out of event.target and return it
 * @param throttleFn The debounce function set up by debounce()
 * @returns A non-throttled function that will first call mutateFn and then call throttleFn
 */
export declare function mutateEach(mutateFn: (...args: Array<any>) => Array<any>, throttleFn: (...args: Array<any>) => any): (...args: Array<any>) => any;
